export function isFxSessionDetail(raw) {
  if (!raw || !raw.trim()) return false;
  try {
    const value = JSON.parse(raw.trim());
    return value?.kind === 'session_detail' && Array.isArray(value.history);
  } catch {
    return false;
  }
}

