// Bookshelf — a tiny book tracker. No accounts, no database, no deps.
// Storage: a single books.json file. Run: node server.js  (default port 3000)
import { createServer } from "node:http";
import { readFile, writeFile } from "node:fs/promises";
import { randomUUID } from "node:crypto";

const PORT = process.env.PORT || 3000;
const DATA_FILE = new URL("./books.json", import.meta.url);

/** @typedef {{id:string,title:string,author:string,notes:string,status:"reading"|"finished",addedAt:string,finishedAt:string|null}} Book */

async function loadBooks() {
  try {
    const raw = await readFile(DATA_FILE, "utf8");
    const data = JSON.parse(raw);
    return Array.isArray(data) ? data : [];
  } catch (err) {
    if (err.code === "ENOENT") return [];
    throw err;
  }
}

async function saveBooks(books) {
  await writeFile(DATA_FILE, JSON.stringify(books, null, 2), "utf8");
}

// ---------- form parsing ----------
async function readBody(req) {
  const chunks = [];
  for await (const c of req) chunks.push(c);
  return Buffer.concat(chunks).toString("utf8");
}

function parseForm(text) {
  const params = new URLSearchParams(text);
  const out = {};
  for (const [k, v] of params) out[k] = v.trim();
  return out;
}

function esc(s) {
  return String(s ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

// ---------- pages ----------
const SHELL = (title, body) => `<!doctype html>
<html lang="en"><head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>${esc(title)} · Bookshelf</title>
<style>
  :root { color-scheme: light; }
  body { font: 16px/1.5 -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
         max-width: 720px; margin: 2rem auto; padding: 0 1rem; color: #1a1a1a; }
  h1 { font-size: 1.5rem; margin: 0 0 1rem; }
  h1 a { color: inherit; text-decoration: none; }
  h2 { font-size: 1.15rem; margin: 1.75rem 0 0.5rem; color: #444; }
  .book { padding: 0.75rem 0; border-bottom: 1px solid #eee; }
  .book:last-child { border-bottom: none; }
  .book .title { font-weight: 600; }
  .book .author { color: #666; font-size: 0.9rem; }
  .book a.title { text-decoration: none; color: #1a1a1a; }
  .book a.title:hover { text-decoration: underline; }
  .meta { font-size: 0.8rem; color: #999; margin-top: 0.2rem; }
  form.inline { display: inline; }
  button, input[type=submit] { cursor: pointer; }
  input, textarea { font: inherit; }
  input[type=text], textarea { width: 100%; box-sizing: border-box;
    padding: 0.4rem 0.5rem; border: 1px solid #ccc; border-radius: 4px; }
  textarea { min-height: 8rem; resize: vertical; }
  label { display: block; margin: 0.5rem 0 0.15rem; font-size: 0.85rem; color: #555; }
  .actions { margin-top: 0.4rem; display: flex; gap: 0.5rem; align-items: center; }
  .btn { background: #2b2b2b; color: #fff; border: none; border-radius: 4px;
    padding: 0.45rem 0.9rem; }
  .btn.ghost { background: transparent; color: #2b2b2b; border: 1px solid #ccc; }
  .empty { color: #999; font-style: italic; padding: 0.5rem 0; }
  .notes { white-space: pre-wrap; margin-top: 0.75rem; }
  a.back { display: inline-block; margin-bottom: 1rem; font-size: 0.9rem; }
</style>
</head><body>
<h1><a href="/">📚 Bookshelf</a></h1>
${body}
</body></html>`;

function bookRow(b) {
  return `<div class="book">
    <a class="title" href="/books/${esc(b.id)}">${esc(b.title)}</a>
    <span class="author">— ${esc(b.author)}</span>
    ${b.status === "reading" ? `<form class="inline" method="post" action="/books/${esc(b.id)}/finish">
      <button class="btn ghost" type="submit">Mark finished</button>
    </form>` : ""}
    <div class="meta">Added ${esc(new Date(b.addedAt).toLocaleDateString())}${
    b.finishedAt ? ` · Finished ${esc(new Date(b.finishedAt).toLocaleDateString())}` : ""
  }</div>
  </div>`;
}

function homePage(books) {
  const reading = books.filter((b) => b.status === "reading");
  const finished = books.filter((b) => b.status === "finished");
  const body = `
    <h2>Add a book</h2>
    <form method="post" action="/books">
      <label for="title">Title</label>
      <input id="title" name="title" type="text" required>
      <label for="author">Author</label>
      <input id="author" name="author" type="text" required>
      <label for="notes">Notes (optional)</label>
      <textarea id="notes" name="notes"></textarea>
      <div class="actions"><button class="btn" type="submit">Add to shelf</button></div>
    </form>
    <h2>Currently reading</h2>
    ${reading.length ? reading.map(bookRow).join("") : '<p class="empty">Nothing in progress yet.</p>'}
    <h2>Finished</h2>
    ${finished.length ? finished.map(bookRow).join("") : '<p class="empty">No finished books yet.</p>'}
  `;
  return SHELL("Bookshelf", body);
}

function bookPage(b) {
  const body = `
    <a class="back" href="/">← Back to shelf</a>
    <div class="book">
      <div class="title" style="font-size:1.25rem">${esc(b.title)}</div>
      <div class="author">by ${esc(b.author)}</div>
      <div class="meta">Added ${esc(new Date(b.addedAt).toLocaleDateString())}${
    b.finishedAt ? ` · Finished ${esc(new Date(b.finishedAt).toLocaleDateString())}` : ""
  }</div>
      ${b.status === "reading" ? `<form class="inline" method="post" action="/books/${esc(b.id)}/finish">
        <div class="actions"><button class="btn ghost" type="submit">Mark finished</button></div>
      </form>` : ""}
    </div>
    <h2>Notes</h2>
    <form method="post" action="/books/${esc(b.id)}/notes">
      <textarea name="notes" placeholder="Add your notes…">${esc(b.notes)}</textarea>
      <div class="actions"><button class="btn" type="submit">Save notes</button></div>
    </form>
  `;
  return SHELL(b.title, body);
}

// ---------- router ----------
function redirect(res, location) {
  res.writeHead(303, { Location: location });
  res.end();
}

function notFound(res) {
  res.writeHead(404, { "Content-Type": "text/html; charset=utf-8" });
  res.end(SHELL("Not found", '<p class="empty">That book isn’t on the shelf.</p><a class="back" href="/">← Back</a>'));
}

const server = createServer(async (req, res) => {
  const url = new URL(req.url, `http://${req.headers.host}`);
  const path = url.pathname;

  try {
    // GET /  — home
    if (req.method === "GET" && path === "/") {
      const books = await loadBooks();
      res.writeHead(200, { "Content-Type": "text/html; charset=utf-8" });
      return res.end(homePage(books));
    }

    // GET /books/:id — detail (the linkable page)
    const detail = path.match(/^\/books\/([^/]+)$/);
    if (req.method === "GET" && detail) {
      const books = await loadBooks();
      const book = books.find((b) => b.id === detail[1]);
      if (!book) return notFound(res);
      res.writeHead(200, { "Content-Type": "text/html; charset=utf-8" });
      return res.end(bookPage(book));
    }

    // POST /books — create
    if (req.method === "POST" && path === "/books") {
      const form = parseForm(await readBody(req));
      if (!form.title || !form.author) {
        res.writeHead(400, { "Content-Type": "text/html; charset=utf-8" });
        return res.end(SHELL("Missing fields", '<p class="empty">Title and author are required.</p><a class="back" href="/">← Back</a>'));
      }
      const books = await loadBooks();
      const book = {
        id: randomUUID(),
        title: form.title,
        author: form.author,
        notes: form.notes || "",
        status: "reading",
        addedAt: new Date().toISOString(),
        finishedAt: null,
      };
      books.push(book);
      await saveBooks(books);
      return redirect(res, "/");
    }

    // POST /books/:id/finish — mark finished
    const finish = path.match(/^\/books\/([^/]+)\/finish$/);
    if (req.method === "POST" && finish) {
      const books = await loadBooks();
      const book = books.find((b) => b.id === finish[1]);
      if (!book) return notFound(res);
      book.status = "finished";
      book.finishedAt = new Date().toISOString();
      await saveBooks(books);
      return redirect(res, "/");
    }

    // POST /books/:id/notes — update notes
    const notes = path.match(/^\/books\/([^/]+)\/notes$/);
    if (req.method === "POST" && notes) {
      const books = await loadBooks();
      const book = books.find((b) => b.id === notes[1]);
      if (!book) return notFound(res);
      book.notes = (parseForm(await readBody(req)).notes || "").slice(0, 20000);
      await saveBooks(books);
      return redirect(res, `/books/${book.id}`);
    }

    return notFound(res);
