import { readFile, writeFile } from "node:fs/promises";
import { randomUUID } from "node:crypto";

const PORT = process.env.PORT || 3000;
const DATA_FILE = new URL("./books.json", import.meta.url);

/** @typedef {{id:string,title:string,author:string,notes:string,status:"reading"|"finished",addedAt:string,finishedAt:string|null}} Book */

async function loadBooks() {
  try {
    const raw = await readFile(DATA_FILE, "utf8");
    const data = JSON.parse(raw);
    return Array.isArray(data) ? data : [];
  } catch (err) {
    if (err.code === "ENOENT") return [];
    throw err;
  }
}

async function saveBooks(books) {
  await writeFile(DATA_FILE, JSON.stringify(books, null, 2), "utf8");
}

// ---------- form parsing ----------
async function readBody(req) {
  const chunks = [];
  for await (const c of req) chunks.push(c);
  return Buffer.concat(chunks).toString("utf8");
}

function parseForm(text) {
  const params = new URLSearchParams(text);
  const out = {};
  for (const [k, v] of params) out[k] = v.trim();
  return out;
}

function esc(s) {
  return String(s ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

// ---------- pages ----------
const SHELL = (title, body) => `<!doctype html>
<html lang="en"><head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
