function bookRow(b) {
  return `<div class="book">
    <a class="title" href="/books/${esc(b.id)}">${esc(b.title)}</a>
    <span class="author">— ${esc(b.author)}</span>
    ${b.status === "reading" ? `<form class="inline" method="post" action="/books/${esc(b.id)}/finish">
      <button class="btn ghost" type="submit">Mark finished</button>
    </form>` : ""}
    <div class="meta">Added ${esc(new Date(b.addedAt).toLocaleDateString())}${
    b.finishedAt ? ` · Finished ${esc(new Date(b.finishedAt).toLocaleDateString())}` : ""
  }</div>
  </div>`;
}

function homePage(books) {
  const reading = books.filter((b) => b.status === "reading");
  const finished = books.filter((b) => b.status === "finished");
  const body = `
    <h2>Add a book</h2>
    <form method="post" action="/books">
      <label for="title">Title</label>
      <input id="title" name="title" type="text" required>
      <label for="author">Author</label>
      <input id="author" name="author" type="text" required>
      <label for="notes">Notes (optional)</label>
      <textarea id="notes" name="notes"></textarea>
      <div class="actions"><button class="btn" type="submit">Add to shelf</button></div>
    </form>
    <h2>Currently reading</h2>
    ${reading.length ? reading.map(bookRow).join("") : '<p class="empty">Nothing in progress yet.</p>'}
    <h2>Finished</h2>
    ${finished.length ? finished.map(bookRow).join("") : '<p class="empty">No finished books yet.</p>'}
  `;
  return SHELL("Bookshelf", body);
}

function bookPage(b) {
  const body = `
    <a class="back" href="/">← Back to shelf</a>
    <div class="book">
      <div class="title" style="font-size:1.25rem">${esc(b.title)}</div>
      <div class="author">by ${esc(b.author)}</div>
      <div class="meta">Added ${esc(new Date(b.addedAt).toLocaleDateString())}${
    b.finishedAt ? ` · Finished ${esc(new Date(b.finishedAt).toLocaleDateString())}` : ""
  }</div>
      ${b.status === "reading" ? `<form class="inline" method="post" action="/books/${esc(b.id)}/finish">
        <div class="actions"><button class="btn ghost" type="submit">Mark finished</button></div>
      </form>` : ""}
    </div>
    <h2>Notes</h2>
    <form method="post" action="/books/${esc(b.id)}/notes">
      <textarea name="notes" placeholder="Add your notes…">${esc(b.notes)}</textarea>
      <div class="actions"><button class="btn" type="submit">Save notes</button></div>
    </form>
  `;
  return SHELL(b.title, body);
}

// ---------- router ----------
function redirect(res, location) {
  res.writeHead(303, { Location: location });
  res.end();
}

function notFound(res) {
  res.writeHead(404, { "Content-Type": "text/html; charset=utf-8" });
  res.end(SHELL("Not found", '<p class="empty">That book isn’t on the shelf.</p><a class="back" href="/">← Back</a>'));
}

const server = createServer(async (req, res) => {
  const url = new URL(req.url, `http://${req.headers.host}`);
  const path = url.pathname;

  try {
    // GET /  — home
    if (req.method === "GET" && path === "/") {
      const books = await loadBooks();
      res.writeHead(200, { "Content-Type": "text/html; charset=utf-8" });
      return res.end(homePage(books));
    }

    // GET /books/:id — detail (the linkable page)
    const detail = path.match(/^\/books\/([^/]+)$/);
    if (req.method === "GET" && detail) {
      const books = await loadBooks();
      const book = books.find((b) => b.id === detail[1]);
      if (!book) return notFound(res);
      res.writeHead(200, { "Content-Type": "text/html; charset=utf-8" });
      return res.end(bookPage(book));
    }

    // POST /books — create
    if (req.method === "POST" && path === "/books") {
      const form = parseForm(await readBody(req));
      if (!form.title || !form.author) {
        res.writeHead(400, { "Content-Type": "text/html; charset=utf-8" });
        return res.end(SHELL("Missing fields", '<p class="empty">Title and author are required.</p><a class="back" href="/">← Back</a>'));
      }
      const books = await loadBooks();
      const book = {
        id: randomUUID(),
        title: form.title,
        author: form.author,
        notes: form.notes || "",
        status: "reading",
        addedAt: new Date().toISOString(),
        finishedAt: null,
      };
      books.push(book);
      await saveBooks(books);
      return redirect(res, "/");
    }

    // POST /books/:id/finish — mark finished
    const finish = path.match(/^\/books\/([^/]+)\/finish$/);
    if (req.method === "POST" && finish) {
      const books = await loadBooks();
      const book = books.find((b) => b.id === finish[1]);
      if (!book) return notFound(res);
      book.status = "finished";
      book.finishedAt = new Date().toISOString();
      await saveBooks(books);
      return redirect(res, "/");
    }

    // POST /books/:id/notes — update notes
    const notes = path.match(/^\/books\/([^/]+)\/notes$/);
    if (req.method === "POST" && notes) {
      const books = await loadBooks();
      const book = books.find((b) => b.id === notes[1]);
      if (!book) return notFound(res);
      book.notes = (parseForm(await readBody(req)).notes || "").slice(0, 20000);
      await saveBooks(books);
      return redirect(res, `/books/${book.id}`);
    }

    return notFound(res);
  } catch (err) {
    console.error(err);
    res.writeHead(500, { "Content-Type": "text/plain; charset=utf-8" });
    res.end("Something went wrong.");
  }
});

server.listen(PORT, () => {
  console.log(`Bookshelf running at http://localhost:${PORT}`);
});
"}

